static Schueler Map(SqliteDataReader r)
{
    int iS = r.GetOrdinal("schnitt");
    return new Schueler(
        r.GetInt32(r.GetOrdinal("id")),
        r.GetString(r.GetOrdinal("name")),
        r.GetString(
            r.GetOrdinal("klasse")),
        r.IsDBNull(iS)
            ? null
            : r.GetDouble(iS));
}

class SchuelerRepository(string cs)
{
    public List<Schueler> InKlasse(
        string klasse)
    {
        using var con =
            new SqliteConnection(cs);
        con.Open();
        using var cmd =
            con.CreateCommand();
        cmd.CommandText = """
          SELECT id, name, klasse, schnitt
          FROM schueler
          WHERE klasse = @k
          """;
        cmd.Parameters
            .AddWithValue("@k", klasse);
        using var r = cmd.ExecuteReader();
        var liste = new List<Schueler>();
        while (r.Read())
            liste.Add(Map(r));
        return liste;
    }
}

public int Einfuegen(Schueler s)
{
    // con, cmd wie oben
    cmd.CommandText = """
      INSERT INTO schueler
        (name, klasse, schnitt)
      VALUES (@n, @k, @s);
      SELECT last_insert_rowid();
      """;
    cmd.Parameters.AddWithValue(
        "@n", s.Name);
    cmd.Parameters.AddWithValue(
        "@k", s.Klasse);
    cmd.Parameters.AddWithValue("@s",
        (object?)s.Schnitt
          ?? DBNull.Value);
    return Convert.ToInt32(
        cmd.ExecuteScalar());
}

